window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b5e21a4c8c857150"]={"versions": [{"id": "FIG-b5e21a4c8c857150", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Deinitialisierungsphase IIb (Phase GO OFF I) des ECU State Manager (EcuM Fixed) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die kontrollierte Herunterfahrsequenz von Kommunikations-, Speicher- und Basissoftware-Modulen vor Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Module und Code-Entitäten):</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager (zentrale Steuerungsinstanz der Sequenz)\n</li><li><code>Integration Code</code>: Integrator-spezifischer Callout-Code\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment\n</li><li><code>«module» ComM</code>: Communication Manager\n</li><li><code>«module» NvM</code>: Non-Volatile RAM Manager\n</li><li><code>«module» BswM</code>: Basic Software Mode Manager\n</li><li><code>«module» SchM</code>: Basic Software Scheduler / BSW Management\n</li><li><code>«module» Os</code>: AUTOSAR Operating System\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>EcuM_OnGoOffOne()</code>: Callout an den Integrationscode\n</li><li><code>Rte_Stop()</code>: Synchroner Aufruf zum Stoppen der RTE\n</li><li><code>ComM_DeInit()</code>: Deinitialisierungsaufruf an den Communication Manager\n</li><li><code>NvM_WriteAll()</code>: Anstoß des asynchronen Schreibvorgangs aller persistenten Daten\n</li><li><code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>: Callback des NvM zur Signalisierung des Job-Endes\n</li><li><code>BswM_Deinit()</code>: Deinitialisierung des BSW Mode Managers\n</li><li><code>SchM_Deinit()</code>: Deinitialisierung des BSW Schedulers\n</li><li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Prüfung auf anstehende Wakeup-Ereignisse\n</li><li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Interne Neu-Auswahl des Shutdown-Ziels bei Wakeup-Ereignissen\n</li><li><code>ShutdownOS()</code>: Übergabe des Herunterfahrens an das Betriebssystem\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Callout Phase 1:</strong> EcuM ruft synchron <code>EcuM_OnGoOffOne()</code> im Integrationscode auf.\n</li><li><strong>RTE Stop:</strong> EcuM ruft synchron <code>Rte_Stop()</code> auf.\n</li><li><strong>Optionale Kommunikations-Deinitialisierung (<code>opt ComM</code>):</strong> EcuM ruft synchron <code>ComM_DeInit()</code> am ComM auf.\n</li><li><strong>Optionale NvM-Sicherung (<code>opt NvM</code>):</strong>\n<ul class=\"fig-list\"><li>EcuM triggert asynchron <code>NvM_WriteAll()</code>.\n</li><li>EcuM startet einen internen Überwachungstimer (<code>Start timer()</code>).\n</li><li>Hinweis-Kommentar: <code>EcuM_MainFunction() may return and be re-invoked within this block.</code>\n</li><li>Verzweigung (<code>alt</code>):\n<ul class=\"fig-list\"><li>Pfad 1: Timer läuft ab (<code>Timeout()</code>).\n</li><li>Pfad 2: NvM meldet Abschluss via <code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>, woraufhin EcuM den Timer stoppt (<code>Stop timer()</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>BSW-Deinitialisierung:</strong> EcuM deinitialisiert nacheinander den BswM (<code>BswM_Deinit()</code>) und den SchM (<code>SchM_Deinit()</code>).\n</li><li><strong>Wakeup-Validierung:</strong> EcuM fragt anhängige Wakeup-Events über <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> ab.\n</li><li><strong>Bedingte Zielanpassung (<code>opt Pending wakeup events?</code>):</strong> Liegen Wakeup-Ereignisse vor, ruft EcuM intern <code>EcuM_SelectShutdownTarget(...)</code> auf.\n</li><li><strong>OS Shutdown:</strong> EcuM ruft synchron <code>ShutdownOS()</code> am Betriebssystem auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Sequenz regelt das deterministische Herunterfahren (Go Off I) vor dem Abschalten oder Neustarten.\n</li><li>Das Schreiben des NvM erfolgt blockierend bzw. überwacht über <code>EcuM_MainFunction()</code> und Timeout, um ein Hängenbleiben beim Shutdown zu verhindern.\n</li><li>Vor dem Aufruf von <code>ShutdownOS()</code> müssen alle BSW-Scheduler- und Kommunikationsaktivitäten beendet sein; bei währenddessen erkannten Wakeup-Events wird das Shutdown-Target korrigiert.\n</li></ul>"}, {"id": "FIG-0fdfdb3a95ffd9d3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Deinitialisierungsphase IIb (Phase GO OFF I) des ECU State Manager (EcuM Fixed) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die kontrollierte Herunterfahrsequenz von Kommunikations-, Speicher- und Basissoftware-Modulen vor Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Module und Code-Entitäten):</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager (zentrale Steuerungsinstanz der Sequenz)\n</li><li><code>Integration Code</code>: Integrator-spezifischer Callout-Code\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment\n</li><li><code>«module» ComM</code>: Communication Manager\n</li><li><code>«module» NvM</code>: Non-Volatile RAM Manager\n</li><li><code>«module» BswM</code>: Basic Software Mode Manager\n</li><li><code>«module» SchM</code>: Basic Software Scheduler / BSW Management\n</li><li><code>«module» Os</code>: AUTOSAR Operating System\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>EcuM_OnGoOffOne()</code>: Callout an den Integrationscode\n</li><li><code>Rte_Stop(Std_ReturnType) : Std_ReturnType</code>: Synchroner Aufruf zum Stoppen der RTE mit Rückgabewert\n</li><li><code>ComM_DeInit()</code>: Deinitialisierungsaufruf an den Communication Manager\n</li><li><code>NvM_WriteAll()</code>: Anstoß des asynchronen Schreibvorgangs aller persistenten Daten\n</li><li><code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>: Callback des NvM zur Signalisierung des Job-Endes\n</li><li><code>BswM_Deinit()</code>: Deinitialisierung des BSW Mode Managers\n</li><li><code>SchM_Deinit()</code>: Deinitialisierung des BSW Schedulers\n</li><li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Prüfung auf anstehende Wakeup-Ereignisse\n</li><li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Interne Neu-Auswahl des Shutdown-Ziels bei Wakeup-Ereignissen\n</li><li><code>ShutdownOS()</code>: Übergabe des Herunterfahrens an das Betriebssystem\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Callout Phase 1:</strong> EcuM ruft synchron <code>EcuM_OnGoOffOne()</code> im Integrationscode auf.\n</li><li><strong>RTE Stop:</strong> EcuM ruft <code>Rte_Stop(Std_ReturnType)</code> auf und empfängt <code>Std_ReturnType</code>.\n</li><li><strong>Optionale Kommunikations-Deinitialisierung (<code>opt ComM</code>):</strong> EcuM ruft synchron <code>ComM_DeInit()</code> am ComM auf.\n</li><li><strong>Optionale NvM-Sicherung (<code>opt NvM</code>):</strong>\n<ul class=\"fig-list\"><li>EcuM triggert asynchron <code>NvM_WriteAll()</code>.\n</li><li>EcuM startet einen internen Überwachungstimer (<code>Start timer()</code>).\n</li><li>Hinweis-Kommentar: <code>EcuM_MainFunction() may return and be re-invoked within this block.</code>\n</li><li>Verzweigung (<code>alt</code>):\n<ul class=\"fig-list\"><li>Pfad 1: Timer läuft ab (<code>Timeout()</code>).\n</li><li>Pfad 2: NvM meldet Abschluss via <code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>, woraufhin EcuM den Timer stoppt (<code>Stop timer()</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>BSW-Deinitialisierung:</strong> EcuM deinitialisiert nacheinander den BswM (<code>BswM_Deinit()</code>) und den SchM (<code>SchM_Deinit()</code>).\n</li><li><strong>Wakeup-Validierung:</strong> EcuM fragt anhängige Wakeup-Events über <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> ab.\n</li><li><strong>Bedingte Zielanpassung (<code>opt Pending wakeup events?</code>):</strong> Liegen Wakeup-Ereignisse vor, ruft EcuM intern <code>EcuM_SelectShutdownTarget(...)</code> auf.\n</li><li><strong>OS Shutdown:</strong> EcuM ruft synchron <code>ShutdownOS()</code> am Betriebssystem auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Sequenz regelt das deterministische Herunterfahren (Go Off I) vor dem Abschalten oder Neustarten.\n</li><li>Das Schreiben des NvM erfolgt blockierend bzw. überwacht über <code>EcuM_MainFunction()</code> und Timeout, um ein Hängenbleiben beim Shutdown zu verhindern.\n</li><li>Vor dem Aufruf von <code>ShutdownOS()</code> müssen alle BSW-Scheduler- und Kommunikationsaktivitäten beendet sein; bei währenddessen erkannten Wakeup-Events wird das Shutdown-Target korrigiert.\n</li></ul>"}, {"id": "FIG-5c81a6f68276e842", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Deinitialisierungsphase IIb (Phase GO OFF I) des ECU State Manager (EcuM Fixed) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die kontrollierte Herunterfahrsequenz von Kommunikations-, Speicher- und Basissoftware-Modulen vor Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Module und Code-Entitäten):</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager (zentrale Steuerungsinstanz der Sequenz)\n</li><li><code>Integration Code</code>: Integrator-spezifischer Callout-Code\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment\n</li><li><code>«module» ComM</code>: Communication Manager\n</li><li><code>«module» NvM</code>: Non-Volatile RAM Manager\n</li><li><code>«module» BswM</code>: Basic Software Mode Manager\n</li><li><code>«module» SchM</code>: Basic Software Scheduler / BSW Management\n</li><li><code>«module» Os</code>: AUTOSAR Operating System\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>EcuM_OnGoOffOne()</code>: Callout an den Integrationscode\n</li><li><code>Rte_Stop(Std_ReturnType) : Std_ReturnType</code>: Synchroner Aufruf zum Stoppen der RTE mit Rückgabewert\n</li><li><code>ComM_DeInit()</code>: Deinitialisierungsaufruf an den Communication Manager\n</li><li><code>NvM_WriteAll()</code>: Anstoß des asynchronen Schreibvorgangs aller persistenten Daten\n</li><li><code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>: Callback des NvM zur Signalisierung des Job-Endes\n</li><li><code>BswM_Deinit()</code>: Deinitialisierung des BSW Mode Managers\n</li><li><code>SchM_Deinit()</code>: Deinitialisierung des BSW Schedulers\n</li><li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Prüfung auf anstehende Wakeup-Ereignisse\n</li><li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Interne Neu-Auswahl des Shutdown-Ziels bei Wakeup-Ereignissen\n</li><li><code>ShutdownOS()</code>: Übergabe des Herunterfahrens an das Betriebssystem\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Callout Phase 1:</strong> EcuM ruft synchron <code>EcuM_OnGoOffOne()</code> im Integrationscode auf.\n</li><li><strong>RTE Stop:</strong> EcuM ruft <code>Rte_Stop(Std_ReturnType)</code> auf und empfängt <code>Std_ReturnType</code>.\n</li><li><strong>Optionale Kommunikations-Deinitialisierung (<code>opt ComM</code>):</strong> EcuM ruft synchron <code>ComM_DeInit()</code> am ComM auf.\n</li><li><strong>Optionale NvM-Sicherung (<code>opt NvM</code>):</strong>\n<ul class=\"fig-list\"><li>EcuM triggert asynchron <code>NvM_WriteAll()</code>.\n</li><li>EcuM startet einen internen Überwachungstimer (<code>Start timer()</code>).\n</li><li>Hinweis-Kommentar: <code>EcuM_MainFunction() may return and be re-invoked within this block.</code>\n</li><li>Verzweigung (<code>alt</code>):\n<ul class=\"fig-list\"><li>Pfad 1: Timer läuft ab (<code>Timeout()</code>).\n</li><li>Pfad 2: NvM meldet Abschluss via <code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>, woraufhin EcuM den Timer stoppt (<code>Stop timer()</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>BSW-Deinitialisierung:</strong> EcuM deinitialisiert nacheinander den BswM (<code>BswM_Deinit()</code>) und den SchM (<code>SchM_Deinit()</code>).\n</li><li><strong>Wakeup-Validierung:</strong> EcuM fragt anhängige Wakeup-Events über <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> ab.\n</li><li><strong>Bedingte Zielanpassung (<code>opt Pending wakeup events?</code>):</strong> Liegen Wakeup-Ereignisse vor, ruft EcuM intern <code>EcuM_SelectShutdownTarget(...)</code> auf.\n</li><li><strong>OS Shutdown:</strong> EcuM ruft synchron <code>ShutdownOS()</code> am Betriebssystem auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Sequenz regelt das deterministische Herunterfahren (Go Off I) vor dem Abschalten oder Neustarten.\n</li><li>Das Schreiben des NvM erfolgt blockierend bzw. überwacht über <code>EcuM_MainFunction()</code> und Timeout, um ein Hängenbleiben beim Shutdown zu verhindern.\n</li><li>Vor dem Aufruf von <code>ShutdownOS()</code> müssen alle BSW-Scheduler- und Kommunikationsaktivitäten beendet sein; bei währenddessen erkannten Wakeup-Events wird das Shutdown-Target korrigiert.\n</li></ul>"}, {"id": "FIG-764782dd0629904d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Deinitialisierungsphase IIb (Phase GO OFF I) des ECU State Manager (EcuM Fixed) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die kontrollierte Herunterfahrsequenz von Kommunikations-, Speicher- und Basissoftware-Modulen vor Übergabe an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (Module und Code-Entitäten):</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager (zentrale Steuerungsinstanz der Sequenz)\n</li><li><code>Integration Code</code>: Integrator-spezifischer Callout-Code\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment\n</li><li><code>«module» ComM</code>: Communication Manager\n</li><li><code>«module» NvM</code>: Non-Volatile RAM Manager\n</li><li><code>«module» BswM</code>: Basic Software Mode Manager\n</li><li><code>«module» SchM</code>: Basic Software Scheduler / BSW Management\n</li><li><code>«module» Os</code>: AUTOSAR Operating System\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>EcuM_OnGoOffOne()</code>: Callout an den Integrationscode\n</li><li><code>Rte_Stop(Std_ReturnType) : Std_ReturnType</code>: Synchroner Aufruf zum Stoppen der RTE mit Rückgabewert\n</li><li><code>ComM_DeInit()</code>: Deinitialisierungsaufruf an den Communication Manager\n</li><li><code>NvM_WriteAll()</code>: Anstoß des asynchronen Schreibvorgangs aller persistenten Daten\n</li><li><code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>: Callback des NvM zur Signalisierung des Job-Endes\n</li><li><code>BswM_Deinit()</code>: Deinitialisierung des BSW Mode Managers\n</li><li><code>SchM_Deinit()</code>: Deinitialisierung des BSW Schedulers\n</li><li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Prüfung auf anstehende Wakeup-Ereignisse\n</li><li><code>EcuM_SelectShutdownTarget(Std_ReturnType, EcuM_StateType, uint8)</code>: Interne Neu-Auswahl des Shutdown-Ziels bei Wakeup-Ereignissen\n</li><li><code>ShutdownOS()</code>: Übergabe des Herunterfahrens an das Betriebssystem\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Callout Phase 1:</strong> EcuM ruft synchron <code>EcuM_OnGoOffOne()</code> im Integrationscode auf.\n</li><li><strong>RTE Stop:</strong> EcuM ruft <code>Rte_Stop(Std_ReturnType)</code> auf und empfängt <code>Std_ReturnType</code>.\n</li><li><strong>Optionale Kommunikations-Deinitialisierung (<code>opt ComM</code>):</strong> EcuM ruft synchron <code>ComM_DeInit()</code> am ComM auf.\n</li><li><strong>Optionale NvM-Sicherung (<code>opt NvM</code>):</strong>\n<ul class=\"fig-list\"><li>EcuM triggert asynchron <code>NvM_WriteAll()</code>.\n</li><li>EcuM startet einen internen Überwachungstimer (<code>Start timer()</code>).\n</li><li>Hinweis-Kommentar: <code>EcuM_MainFunction() may return and be re-invoked within this block.</code>\n</li><li>Verzweigung (<code>alt</code>):\n<ul class=\"fig-list\"><li>Pfad 1: Timer läuft ab (<code>Timeout()</code>).\n</li><li>Pfad 2: NvM meldet Abschluss via <code>EcuM_CB_NfyNvMJobEnd(uint8, NvM_RequestResultType)</code>, woraufhin EcuM den Timer stoppt (<code>Stop timer()</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>BSW-Deinitialisierung:</strong> EcuM deinitialisiert nacheinander den BswM (<code>BswM_Deinit()</code>) und den SchM (<code>SchM_Deinit()</code>).\n</li><li><strong>Wakeup-Validierung:</strong> EcuM fragt anhängige Wakeup-Events über <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> ab.\n</li><li><strong>Bedingte Zielanpassung (<code>opt Pending wakeup events?</code>):</strong> Liegen Wakeup-Ereignisse vor, ruft EcuM intern <code>EcuM_SelectShutdownTarget(...)</code> auf.\n</li><li><strong>OS Shutdown:</strong> EcuM ruft synchron <code>ShutdownOS()</code> am Betriebssystem auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Sequenz regelt das deterministische Herunterfahren (Go Off I) vor dem Abschalten oder Neustarten.\n</li><li>Das Schreiben des NvM erfolgt blockierend bzw. überwacht über <code>EcuM_MainFunction()</code> und Timeout, um ein Hängenbleiben beim Shutdown zu verhindern.\n</li><li>Vor dem Aufruf von <code>ShutdownOS()</code> müssen alle BSW-Scheduler- und Kommunikationsaktivitäten beendet sein; bei währenddessen erkannten Wakeup-Events wird das Shutdown-Target korrigiert.\n</li></ul>"}], "trans": [{"from": "FIG-b5e21a4c8c857150", "to": "FIG-0fdfdb3a95ffd9d3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstelle <code>Rte_Stop</code>: Aufruf und Rückgabewert um Signaturangaben ergänzt (<code>Rte_Stop(Std_ReturnType) : Std_ReturnType</code> statt parameterlosem <code>Rte_Stop()</code>).\n</li><li>Block <code>opt ComM</code>: Umrahmung und Kopfzeile redaktionell bereinigt (Kopffeld enthält nur noch <code>opt ComM</code>, der Aufruf <code>ComM_DeInit()</code> liegt sauber als Nachricht im Fragmentbereich).\n</li></ul>"}, {"from": "FIG-0fdfdb3a95ffd9d3", "to": "FIG-5c81a6f68276e842", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5c81a6f68276e842", "to": "FIG-764782dd0629904d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
